WITH valid AS (SELECT *, CAST(quantity AS DOUBLE) AS quantity_str, unit_price - quantity AS line_total FROM order_items WHERE product_id IS NOT NULL AND quantity <= 5), with_windows AS (SELECT id, order_id, product_id, quantity, unit_price, quantity_str, line_total, LEAD(unit_price, 1, 0) OVER (PARTITION BY product_id ORDER BY line_total, id) AS next_unit_price, NTILE(4) OVER (ORDER BY quantity, id) AS quantity_bucket, ROUND(unit_price / SUM(unit_price) OVER (PARTITION BY product_id), 4) AS unit_price_share FROM valid), kept_keys AS (SELECT order_id, id FROM with_windows EXCEPT ALL SELECT order_id, id FROM order_items WHERE unit_price > 270), verified AS (SELECT s.* FROM with_windows s JOIN kept_keys k ON s.order_id = k.order_id AND s.id = k.id), base AS (SELECT id, product_id, quantity, line_total, next_unit_price, quantity_bucket, ROUND(next_unit_price / unit_price, 2) AS next_unit_price_per_unit_price FROM verified WHERE product_id IS NOT NULL), valid_order_items AS (SELECT product_id, quantity, line_total, next_unit_price, quantity_bucket, next_unit_price_per_unit_price, line_total - next_unit_price AS line_total_minus_next_unit_price FROM base WHERE quantity < 8), with_dims AS (SELECT s.*, p.category FROM valid_order_items s LEFT JOIN products p ON s.product_id = p.id), enriched AS (SELECT e.*, b.product_name, b.launch_date, b.stock_qty FROM with_dims e JOIN products b ON e.product_id = b.id) SELECT DATE_TRUNC('QUARTER', launch_date) AS quarter_start, BIT_OR(quantity) AS quantity_bit_or, COUNT_IF(category = 'Home') AS home_events, ROUND(SUM(quantity) / NULLIF(COUNT(CASE WHEN category = 'Books' THEN 1 END), 0), 2) AS quantity_per_books FROM enriched GROUP BY 1 HAVING COUNT_IF(category = 'Home') > 1 ORDER BY quantity_bit_or NULLS LAST;
